L["resurrection: %d left alone -- out of reach or out of sight."] = "复活：%d人未推荐——超出范围或不在视野内。"
L["resurrection: %d left alone -- flagged for PvP."] = "复活：%d人未推荐——处于PvP状态。"
L["resurrection: %d resting after your press, until they live or the cast is seen to fail."] = "复活：%d人在你按下后暂缓，直到他们复活或确认施法失败。"
L["|cffff8080%s was not resurrected|r -- %s."] = "|cffff8080没有复活%s|r——%s。"
