L["%s: your main hand already carries a temporary enchant."] = "%s：你的主手已有临时附魔。"
L["%s: a pet is out."] = "%s：已有宠物在外。"
L["%s: %s is up."] = "%s：已有%s。"
L["%s: you have no %s in your bags."] = "%s：背包中没有%s。"
L["%s: %s needs level %d."] = "%s：%s需要%d级。"
L["%s: %s needs Fishing %d."] = "%s：%s需要钓鱼%d。"
L["%s: there is no weapon in that hand."] = "%s：那只手没有武器。"
