L["Whispers |cffffffff%s|r: |cffffffff%s|r"] = "密语|cffffffff%s|r：|cffffffff%s|r"
L["Casts nothing and leaves your target alone."] = "不施放任何法术，也不改变你的目标。"
L["asking for buffs: off -- %s is not ticked."] = "请求增益：关闭——未勾选%s。"
L["asking for buffs: held back -- nobody is asked in a fight."] = "请求增益：暂不请求——战斗中不向任何人请求。"
L["asking for buffs: held back -- nobody is asked in a battleground or an arena."] = "请求增益：暂不请求——战场和竞技场中不向任何人请求。"
L["asking for buffs: held back in a city or an inn -- tick %s to ask there too."] = "请求增益：在城市或旅店中暂不请求——勾选%s后在那里也会请求。"
L["Ask in cities and inns too"] = "也在城市和旅店中请求"
L["asking for buffs: held back -- you asked somebody %s ago, and one ask in two minutes is the most."] = "请求增益：暂不请求——你在%s前向别人请求过，两分钟内最多请求一次。"
L["asking for buffs: |cffffffff%s|r can be asked for %s."] = "请求增益：可以向|cffffffff%s|r请求%s。"
L["asking for buffs: on -- nobody in your group or beside you could give you a buff you are missing right now."] = "请求增益：开启——此刻你的队伍里和身边没有人能给你缺少的增益。"
L["asked |cffffffff%s|r %s ago -- not again for the same buff for ten minutes."] = "已在|cffffffff%s|r处请求（%s前）——十分钟内不再请求同一个增益。"
