L["not thanked: %s."] = "未道谢：%s。"
L["they are out of sight now"] = "对方已不在视野内"
L["not thanking |cffffffff%s|r this time."] = "这次不向|cffffffff%s|r道谢。"
L["clear your target to thank them"] = "清除目标后才能道谢"
L["for %s -- they buffed you"] = "为了%s——对方给你加了增益"
L["Buffed you a moment ago. A press thanks them as you have set it up; a right-click lets it go."] = "刚才给你加了增益。按一下会按你的设置道谢；右键点击则放弃。"
L["Emote: one of your thank emotes, with nobody targeted"] = "表情：你的道谢表情之一，不选目标"
L["Emote: |cffffffff%s|r with nobody targeted"] = "表情：|cffffffff%s|r，不选目标"
L["Emote: one of your thank emotes, at |cffffffff%s|r"] = "表情：你的道谢表情之一，对|cffffffff%s|r"
L["Emote: |cffffffff%s|r at |cffffffff%s|r"] = "表情：|cffffffff%s|r，对|cffffffff%s|r"
L["Whispers |cffffffff%s|r a thank-you"] = "密语向|cffffffff%s|r道谢"
L["Right-click: let it go, nothing is sent."] = "右键：放弃，不发送任何内容。"
L["ask me before thanking: |cff00ff00on|r"] = "道谢前先询问我：|cff00ff00开启|r"
L["waiting for your press to thank: |cffffffff%s|r, %ds left"] = "等待你按下以道谢：|cffffffff%s|r，还剩%d秒"
L["%s wags happily."] = "%s开心地摇着尾巴。"
L["%s leans in."] = "%s凑了过来。"
L["%s taps a foreleg twice."] = "%s用前腿轻点了两下。"
L["%s rumbles contentedly."] = "%s满足地低吼着。"
L["%s grunts and snuffles."] = "%s哼哼着嗅来嗅去。"
L["%s blinks slowly."] = "%s慢慢眨了眨眼。"
L["%s ruffles up, feathers puffed."] = "%s蓬起了羽毛。"
L["%s clacks both claws."] = "%s咔嗒咔嗒地敲着双钳。"
L["%s thumps the ground twice."] = "%s咚咚捶了两下地面。"
L["%s chirps and bobs."] = "%s啾啾叫着点头。"
