L["%s lowers the stinger."] = "%s放下了尾刺。"
L["%s peeks out of the shell."] = "%s从壳里探出头来。"
L["%s squeaks."] = "%s吱吱叫了一声。"
L["%s cackles softly."] = "%s轻声咯咯笑。"
L["%s hoots once."] = "%s咕咕叫了一声。"
L["%s coils closer."] = "%s盘绕着靠近了些。"
L["%s trills."] = "%s发出一串鸣叫。"
L["%s rattles, spines raised."] = "%s竖起尖刺，咔咔作响。"
L["%s flickers and reappears."] = "%s闪了一下，又出现了。"
L["%s puffs a few spores."] = "%s噗地喷出几颗孢子。"
L["%s ripples gently."] = "%s轻轻地荡漾着。"
L["%s flicks a tongue out."] = "%s吐了吐信子。"
L["%s yips softly."] = "%s轻轻叫了一声。"
L["%s nuzzles closer."] = "%s蹭了过来。"
L["%s stays close."] = "%s紧紧跟在身边。"
